    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-2: #eef3f9;
        --text: #122033;
        --muted: #5d6b82;
        --border: #cfd8e6;
        --accent: #2457ff;
        --accent-strong: #1d46cc;
        --shadow: 0 24px 60px rgba(18, 32, 51, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0%, #f4f7fb 36%, #e8eef8 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-180%);
        background: var(--surface);
        color: var(--text);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        border: 1px solid var(--border);
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem;
      }

      .card {
        width: min(100%, 28rem);
        background: color-mix(in srgb, var(--surface) 92%, transparent);
        backdrop-filter: blur(18px);
        border: 1px solid rgba(207, 216, 230, 0.75);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: 2rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        font-size: 0.875rem;
        font-weight: 600;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.25rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0.75rem 0 1.5rem;
        color: var(--muted);
        line-height: 1.5;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.75rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: var(--surface-2);
      }

      .checkbox-row {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
      }

      .checkbox-row input {
        inline-size: 1.125rem;
        block-size: 1.125rem;
        margin-top: 0.2rem;
        accent-color: var(--accent);
      }

      .checkbox-row label {
        font-weight: 600;
        line-height: 1.4;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        line-height: 1.45;
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.25rem;
        font: inherit;
        font-weight: 600;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), #3c78ff);
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(36, 87, 255, 0.22);
      }

      button:hover {
        background: linear-gradient(135deg, var(--accent-strong), var(--accent));
      }

      button:focus-visible,
      input:focus-visible,
      a:focus-visible {
        outline: 3px solid #0f62fe;
        outline-offset: 3px;
      }

      footer {
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.875rem;
      }

      @media (max-width: 480px) {
        .page {
          padding: 1rem;
        }

        .card {
          padding: 1.25rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: CanvasText;
          --accent: ButtonText;
          --accent-strong: ButtonText;
        }

        .card,
        .form-field,
        button,
        .skip-link {
          border: 1px solid ButtonBorder;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const h = (tag, attrs = {}, children = []) => ({ tag, attrs, children });

      const ConsentField = () =>
        h("div", { class: "form-field" }, [
          h("div", { class: "checkbox-row" }, [
            h("input", {
              id: "terms",
              name: "terms",
              type: "checkbox",
              required: true,
              "aria-describedby": "terms-help",
            }),
            h("label", { for: "terms" }, ["I agree to the Terms of Use"]),
          ]),
          h("p", { id: "terms-help", class: "helper-text" }, [
            "Please confirm before continuing."
          ]),
        ]);

      const SubmitButton = () =>
        h("div", { class: "actions" }, [
          h("button", { type: "submit" }, ["Continue"]),
        ]);

      const App = () =>
        h("main", { class: "page", id: "main-content" }, [
          h("section", { class: "card", "aria-labelledby": "page-title" }, [
            h("p", { class: "eyebrow" }, ["Consent"]),
            h("h1", { id: "page-title" }, ["Agree to the terms"]),
            h("p", { class: "intro" }, [
              "Review the brief consent below and submit when you're ready."
            ]),
            h("form", { action: "#", method: "post" }, [
              ConsentField(),
              SubmitButton(),
            ]),
            h("footer", {}, ["You can only submit after checking the box."]),
          ]),
        ]);

      const renderNode = (node) => {
        if (typeof node === "string") return document.createTextNode(node);
        const el = document.createElement(node.tag);
        for (const [key, value] of Object.entries(node.attrs || {})) {
          if (value === false || value == null) continue;
          if (key === "class") {
            el.className = value;
          } else if (key in el) {
            el[key] = value;
          } else {
            el.setAttribute(key, String(value));
          }
        }
        for (const child of node.children || []) {
          el.appendChild(renderNode(child));
        }
        return el;
      };

      document.getElementById("app").appendChild(renderNode(App()));
    </script>
  </body>
</html>
